from collections import Counter
def comps(grid,bg):
    h,w=len(grid),len(grid[0]); seen=[[False]*w for _ in range(h)]; res=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=bg and not seen[i][j]:
                stack=[(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    r,c=stack.pop(); cells.append((r,c))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<h and 0<=nc<w and not seen[nr][nc] and grid[nr][nc]!=bg:
                            seen[nr][nc]=True; stack.append((nr,nc))
                res.append(cells)
    return res
def transform(grid):
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    cs=comps(grid,bg)
    stencil=max(cs,key=len)
    rs=[r for r,c in stencil]; cs_=[c for r,c in stencil]
    top,left=min(rs),min(cs_); h=max(rs)-top+1; w=max(cs_)-left+1
    pat=[[grid[top+i][left+j] for j in range(w)] for i in range(h)]
    out=[row[:] for row in grid]
    for m in cs:
        if len(m)==1:
            r,c=m[0]
            cy,cx=h//2,w//2
            for i in range(h):
                for j in range(w):
                    nr,nc=r-cy+i,c-cx+j
                    if 0<=nr<len(grid) and 0<=nc<len(grid[0]):
                        out[nr][nc]=pat[i][j]
    return out
r=transform(inp)
print(r==out)
